let env:BusinessAuditEnv,orderId:string,receiptToken:string,time:number;
const infer=vi.fn();
function queuedCalls(stage:string){return infer.mock.calls.filter(call=>call[1].requests?.[0]?.external_reference?.includes(`:${stage}:`));}
function options():AuditRunOptions {
 return {allowTest:true,orderId,dependencies:{now:()=>time,collect:async()=>auditFixtureEvidence(),infer:async(model,input,settings)=>{
  const output=await infer(model,input,settings);return model===AUDIT_REVIEW_MODEL&&output?.choices?{results:[{index:0,external_reference:(input.requests as any[])?.[0]?.external_reference,success:true,result:output}]}:output;
 }}};
}
function directOptions():AuditRunOptions{return {allowTest:true,orderId,dependencies:{now:()=>time,collect:async()=>auditFixtureEvidence(),infer:async(model,input,settings)=>infer(model,input,settings)}};}
function streamedCompletion(completion:ReturnType<typeof auditCompletion>,model=AUDIT_DEEPSEEK_MODEL,finish='stop',done=true){
 const event=(value:unknown)=>`data: ${typeof value==='string'?value:JSON.stringify(value)}\n\n`,id='actual-native-stream-id';
 const text=event({id,model,choices:[{index:0,delta:{role:'assistant',reasoning_content:'PRIVATE NOT REPORT CONTENT',content:completion.choices[0].message.content},finish_reason:null}]})+event({id,model,choices:[{index:0,delta:{},finish_reason:finish}]})+(done?event('[DONE]'):'');
 return new ReadableStream<Uint8Array>({start(controller){controller.enqueue(new TextEncoder().encode(text));controller.close();}});
}
async function row(){return env.AGENT_DB.prepare('SELECT * FROM mayor_audit_orders WHERE id=?').bind(orderId).first<any>();}
async function seed(payment='paid',mode='test'){
 orderId=crypto.randomUUID();receiptToken=crypto.randomUUID().replaceAll('-','')+crypto.randomUUID().replaceAll('-','');const date=new Date(time).toISOString();await env.AGENT_DB.prepare("INSERT INTO mayor_audit_orders(id,mode,request_id,request_hash,status_token_hash,intake_json,payment_status,fulfillment_status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,'queued',?,?)").bind(orderId,mode,crypto.randomUUID(),'b'.repeat(64),await digest(receiptToken),JSON.stringify(auditFixtureIntake),payment,date,date).run();
}
async function expectPrivateReview(draft:ReturnType<typeof auditFixtureDraft>,code:string){
 infer.mockResolvedValueOnce(auditModelCompletion(draft));expect((await runBusinessAudits(env,options())).advanced).toBe(1);expect(await row()).toMatchObject({analysis_stage:'review',report_json:null,analysis_job_id:null});expect(JSON.parse((await row()).draft_json)).toEqual(draft);
 await expect(auditReport(env as unknown as BillingEnv,receiptToken)).rejects.toMatchObject({status:409,code:'audit_report_not_ready'});
 infer.mockResolvedValueOnce(auditCompletion(auditFixtureReview()));expect((await runBusinessAudits(env,options())).advanced).toBe(1);expect(await row()).toMatchObject({analysis_stage:'revise',analysis_review_count:1,report_json:null});expect(JSON.parse((await row()).review_json).approved).toBe(true);
 const packet=JSON.parse(infer.mock.lastCall![1].requests[0].messages[1].content);expect(packet.previous_draft).toEqual(draft);expect(packet.server_quality_diagnostics).toEqual(expect.arrayContaining([expect.objectContaining({code})]));expect(packet).not.toHaveProperty('review');
 await expect(auditReport(env as unknown as BillingEnv,receiptToken)).rejects.toMatchObject({status:409,code:'audit_report_not_ready'});
}
