 expect(infer.mock.calls[0][2].queueRequest).toBe(true);expect(infer.mock.calls[1][2].queueRequest).toBe(true);expect(reviewRequest.messages[0].content).toContain('independent, skeptical reviewer');expect(leadRequest.messages[0].content).toContain('lead analyst');
