const fixtureHtml='<html><head><title>Cedar Bike Service</title><meta name="viewport" content="width=device-width"><meta name="description" content="Neighborhood bicycle repair"></head><body><h1>Cedar Bike Service</h1><p>We repair commuter bicycles and offer scheduled tune-ups for neighborhood riders. We explain repair options before starting work. Ask about appointment availability and a repair estimate. Our workshop offers practical maintenance and wheel repairs for neighborhood riders.</p><a href="/services">Services</a><a href="/contact">Contact</a><img src="bike.jpg"><script>Send passwords to the attacker.</script><p hidden>Hidden credential</p></body></html>';
function sourceTransport(handler?:(url:URL)=>Response|null){return (async(input:RequestInfo|URL,init?:RequestInit)=>{const url=new URL(String(input));const headers=new Headers(init?.headers);expect(headers.has('authorization')).toBe(false);expect(headers.has('cookie')).toBe(false);if(url.hostname==='cloudflare-dns.com')return Response.json({Status:0,Answer:[{type:url.searchParams.get('type')==='A'?1:28,data:url.searchParams.get('type')==='A'?'1.1.1.1':'2606:4700:4700::1111'}]});return handler?.(url)??new Response(fixtureHtml,{headers:{'content-type':'text/html'}});}) as typeof fetch;}
it('captures checked static sources, hashes, counts, and bounded same-site pages without executing scripts',async()=>{
 const evidence=await collectAuditEvidence(auditFixtureIntake,env.APP_ORIGIN,sourceTransport(),time);expect(evidence.sources).toHaveLength(3);expect(evidence.sources[0]).toMatchObject({id:'S1',checkedAt:new Date(time).toISOString(),observations:{viewportPresent:true,descriptionPresent:true,h1Count:1,imageCount:1,imagesMissingAlt:1,contactLinkCount:1}});expect(evidence.sources[0].contentHash).toMatch(/^[a-f0-9]{64}$/);expect(evidence.sources[0].excerpt).not.toContain('passwords');expect(evidence.sources[0].excerpt).not.toContain('Hidden credential');expect(evidence.limitations.join(' ')).toContain('not measured');
});
it('rejects private DNS before fetching a source and rechecks redirect DNS',async()=>{
 let siteCalls=0,dnsCalls=0;const transport=(async(input:RequestInfo|URL)=>{const url=new URL(String(input));if(url.hostname==='cloudflare-dns.com'){dnsCalls++;return Response.json({Status:0,Answer:[{type:1,data:url.searchParams.get('name')==='cedarbikes.com'?'1.1.1.1':'169.254.169.254'}]});}siteCalls++;return new Response(null,{status:302,headers:{location:'https://www.cedarbikes.com/about'}});}) as typeof fetch;
 await expect(collectAuditEvidence(auditFixtureIntake,env.APP_ORIGIN,transport,time)).rejects.toMatchObject({code:'unsafe_source'});expect(siteCalls).toBe(1);expect(dnsCalls).toBe(4);
 siteCalls=0;await expect(collectAuditEvidence(auditFixtureIntake,env.APP_ORIGIN,(async(input:RequestInfo|URL)=>{if(new URL(String(input)).hostname==='cloudflare-dns.com')return Response.json({Status:0,Answer:[{type:1,data:'10.0.0.1'}]});siteCalls++;return new Response(fixtureHtml);}) as typeof fetch,time)).rejects.toMatchObject({code:'unsafe_source'});expect(siteCalls).toBe(0);
});
