 env.MAYOR_AUDIT_INFERENCE_MODE='streaming';env.MAYOR_AUDIT_MODEL=AUDIT_DEEPSEEK_MODEL;await runBusinessAudits(env,directOptions());let started!:()=>void,controller!:ReadableStreamDefaultController<Uint8Array>;const ready=new Promise<void>(resolve=>{started=resolve;}),cancel=vi.fn();
